-- NEVAHEX Executor VM
local s=""
local m=54321
local function g()
  local r=""
  for i=1,#s,2 do
    m=(m*1103515245+12345)&0x7fffffff
    local b=tonumber(s:sub(i,i+1),16)
    r=r..string.char(b~=(m&0xff))
  end
  return r
end
local f=loadstring or load
local code=g()
if code and #code>0 then
  local fn=f(code)
  if fn then fn() end
end